                    if (q.type === 'classic') {
                        h += '<textarea class="osc-classic-input osc-ex-yazi" rows="5" placeholder="Cevabınızı buraya yazın...">' + oscEsc(a || '') + '</textarea><div class="osc-ex-not">Cevabın sınav bitince değerlendirilir.</div>';
                    } else if (q.type === 'gap') {
