                    byId('osc-render-area-' + quizId).querySelectorAll('.osc-opt-btn').forEach(function (b) { b.classList.toggle('secili', b.dataset.k === state.answers[state.idx]); });
                    oscOptikGuncelle(state.idx); oscUstGuncelle(); oscKaydetPlan();
