                function oscSonucGoster(r, kayit, otomatik) {
                    state.history = r.hist; state.correct = r.d; state.wrong = r.y; state.empty = r.b;
                    oscEl('.osc-quiz').style.display = 'none';
                    oscEl('.osc-start').style.display = 'none';
                    oscEl('.osc-result').style.display = 'block';
                    byId('osc-final-score-' + quizId).innerText = r.puan;
                    byId('osc-stat-correct-' + quizId).innerText = oscSay(r.d);
                    byId('osc-stat-wrong-' + quizId).innerText = oscSay(r.y);
                    byId('osc-stat-empty-' + quizId).innerText = r.b;
                    byId('osc-stat-net-' + quizId).innerText = r.net;
                    const kl = byId('osc-net-kural-' + quizId);
                    if (kl) kl.innerHTML = '<b>' + oscEsc(EXAM.ad) + '</b> · ' + (EXAM.kural > 0 ? EXAM.kural + ' yanlış 1 doğruyu götürür' : 'yanlışlar doğruyu götürmez') + (r.n ? ' · ' + r.n + ' açık uçlu soru puana katılmadı' : '');
                    const ot = byId('osc-oto-' + quizId); if (ot) ot.style.display = otomatik ? 'block' : 'none';
                    const ka = byId('osc-konu-' + quizId); if (ka) ka.innerHTML = oscKonuHtml(r);
                    if (OT) {
                        ['#osc-name-input-area-' + quizId, '#osc-leaderboard-' + quizId].forEach(function (s) { const e = document.querySelector(s); if (e) e.style.display = 'none'; });
                        document.querySelectorAll('#osc-app-' + quizId + ' .osc-share-buttons, #osc-app-' + quizId + ' .osc-actions > .osc-btn-modern-restart').forEach(function (e) { e.style.display = 'none'; });
                        const ac = byId('osc-sp-sonuc-' + quizId);
                        if (ac) { ac.style.display = 'block'; ac.innerHTML = r.anahtarVar ? '<button type="button" class="osc-btn-modern-restart" onclick="oscShowMistakes(' + quizId + ')" style="width:100%;justify-content:center;background:#fef2f2;border-color:#fecaca;color:#991b1b"><span class="dashicons dashicons-visibility"></span> Yanlışları ve doğru cevapları incele</button><div id="osc-mistakes-area-' + quizId + '" style="display:none;text-align:left;margin:12px 0 0;padding:20px;background:#f8fafc;border-radius:12px;border:2px dashed #cbd5e1"></div>' : '<div class="osc-sp-not">Doğru cevaplar öğretmenin oturumu bitirince burada açılacak.</div>'; }
                    }
                    if (kayit) {
                        sfxFinish.play().catch(function () {});
                        const fd = new URLSearchParams(); fd.append('action', 'osc_track_solve'); fd.append('quiz_id', quizId); fd.append('parent_id', <?php echo get_the_ID() ? get_the_ID() : $post_id; ?>);
                        fetch(OSC_AJAX, { method: 'POST', body: fd }).catch(function () {});
                        if (config.uye && config.cn) {
                            const kz = {}; Object.keys(r.konular).forEach(function (k) { if (k !== '—' && r.konular[k].t > 0) kz[k] = r.konular[k]; });
                            const yl = []; r.durum.forEach(function (x, i) { if (x === 'y' || x === 'b') yl.push(i + 1); });
                            oscAjax('osc_sp_cozum_kaydet', { nonce: config.cn, quiz_id: quizId, d: r.d, y: r.y, b: r.b, net: r.net, puan: r.puan, soru: N, konu: JSON.stringify(kz), yanlis: yl.join(','), url: config.url || location.href.split('#')[0] }).catch(function () {});
                        } else if (config.uye_url && ka) {
                            ka.insertAdjacentHTML('afterend', '<a class="osc-uye-davet" href="' + oscEsc(config.uye_url + (config.uye_url.indexOf('?') < 0 ? '?' : '&') + 'git=' + encodeURIComponent(location.href.split('#')[0])) + '">📈 <b>Sonuçlarını kaydet, gelişimini takip et.</b> Ücretsiz öğrenci üyeliği ile çözdüğün testler, netlerin ve konu karnen panelinde birikir →</a>');
                        }
                        if (r.puan >= 50 && typeof confetti === 'function') {
                            var son = Date.now() + 3000, def = { startVelocity: 30, spread: 360, ticks: 60, zIndex: 9999, colors: ['#6366f1', '#8b5cf6', '#10b981', '#f59e0b', '#ec4899'] };
                            var iv = setInterval(function () { var kalan = son - Date.now(); if (kalan <= 0) return clearInterval(iv); confetti(Object.assign({}, def, { particleCount: 50 * (kalan / 3000), origin: { x: Math.random(), y: Math.random() - 0.2 } })); }, 250);
                        }
                    }
                    const res = oscEl('.osc-result'); if (res && res.getBoundingClientRect().top < 0) res.scrollIntoView({ behavior: 'smooth', block: 'start' });
                }

                function finish(otomatik) {
                    if (state.finished) return;
                    state.finished = true; clearInterval(state.timer); clearInterval(state.izle);
                    const kutu = byId('osc-onay-' + quizId); if (kutu) kutu.style.display = 'none';
                    if (document.fullscreenElement || document.webkitIsFullScreen) { try { window.oscExitFS(); } catch (e) {} }
                    if (OT) { oscTeslim(otomatik); return; }
                    oscSonucGoster(oscPuanla(), true, otomatik);
                }

                /* ---- canlı sınıf / ödev oturumu ---- */
                function oscAjax(action, data) {
                    const fd = new URLSearchParams(); fd.append('action', action);
                    Object.keys(data || {}).forEach(function (k) { fd.append(k, data[k]); });
                    return fetch(OSC_AJAX, { method: 'POST', body: fd, credentials: 'same-origin' }).then(function (r) { return r.json(); });
                }
                function oscOt(ek) { return Object.assign({ kod: OT.kod, token: OT.token }, ek || {}); }
                let oscKayitT = null;
                function oscKaydetPlan() { if (!OT || state.finished) return; clearTimeout(oscKayitT); oscKayitT = setTimeout(oscKaydetSimdi, 1200); }
                function oscKaydetSimdi() { if (!OT || state.finished) return; clearTimeout(oscKayitT); oscAjax('osc_sp_kaydet', oscOt({ cevaplar: JSON.stringify(state.answers) })).catch(function () {}); }
                document.addEventListener('visibilitychange', function () {
                    if (document.visibilityState !== 'hidden' || !OT || !state.started || state.finished || !navigator.sendBeacon) return;
                    const fd = new FormData(); fd.append('action', 'osc_sp_kaydet'); fd.append('kod', OT.kod); fd.append('token', OT.token); fd.append('cevaplar', JSON.stringify(state.answers));
                    navigator.sendBeacon(OSC_AJAX, fd);
                });
                function oscTeslim(otomatik) {
                    const area = byId('osc-render-area-' + quizId);
                    oscEl('.osc-quiz').classList.add('osc-gonderiliyor');
                    const dene = function (n) {
                        oscAjax('osc_sp_teslim', oscOt({ cevaplar: JSON.stringify(state.answers) })).then(function (res) {
                            oscEl('.osc-quiz').classList.remove('osc-gonderiliyor');
                            if (!res || !res.success) { state.finished = false; alert((res && res.data) || 'Teslim edilemedi.'); return; }
                            oscOturumSonuc(res.data, otomatik);
                        }).catch(function () {
                            if (n < 4) setTimeout(function () { dene(n + 1); }, 2000 * (n + 1));
                            else { oscEl('.osc-quiz').classList.remove('osc-gonderiliyor'); state.finished = false; alert('İnternet bağlantısı yok gibi görünüyor. Bağlantı gelince “Sınavı Bitir” düğmesine tekrar basın; cevaplarınız kaybolmaz.'); }
                        });
                    };
                    dene(0);
                }
                function oscOturumSonuc(data, otomatik) {
                    if (data.anahtar) data.anahtar.forEach(function (a, i) { const q = config.questions[i]; if (!q) return; if (q.type === 'gap' || q.type === 'classic') q.options = { A: a }; else q.correct = a; });
                    const cev = Array.isArray(data.cevaplar) ? data.cevaplar : state.answers;
                    const hist = data.sonuc.durum.map(function (s, i) { const q = config.questions[i] || {}, a = cev[i]; return { qIdx: i, isCorrect: s === 'd', skipped: s === 'b', userKey: (q.type === 'gap' || q.type === 'classic') ? undefined : (a || undefined), userAns: (q.type === 'gap' || q.type === 'classic') ? (a || '') : undefined, verdict: s === 'n' ? 'nomodel' : (s === 'b' ? 'empty' : 'mismatch') }; });
                    const r = oscOzetle(data.sonuc.durum, hist); r.anahtarVar = !!data.anahtar;
                    state.finished = true; state.started = true;
                    oscSonucGoster(r, false, otomatik);
                    if (!data.anahtar) {
                        const bekle = setInterval(function () {
                            oscAjax('osc_sp_durum', oscOt()).then(function (x) { if (x && x.success && x.data.anahtar) { clearInterval(bekle); oscOturumSonuc(x.data.sonuc_veri, false); } }).catch(function () {});
                        }, 15000);
                    }
                }
                function oscIzle() {
                    clearInterval(state.izle);
                    state.izle = setInterval(function () {
                        if (state.finished) return clearInterval(state.izle);
                        oscAjax('osc_sp_durum', oscOt()).then(function (x) {
                            if (!x || !x.success) return;
                            if (x.data.durum === 'bitti') { finish(true); return; }
                            if (x.data.kalan > 0 && Math.abs(state.deadline - (Date.now() + x.data.kalan * 1000)) > 4000) oscZamanlayici(x.data.kalan);
                        }).catch(function () {});
                    }, 8000);
                }
                function oscOturumAc() {
                    const kutu = byId('osc-sp-durum-' + quizId); if (!kutu) return;
                    if (OT.katilim_durum === 'bitti' && OT.sonuc_veri) { oscOturumSonuc(OT.sonuc_veri, false); return; }
                    if (OT.durum === 'bitti') { kutu.innerHTML = '<div class="osc-sp-mesaj kirmizi">Bu oturum sona erdi.</div>'; return; }
                    if (OT.tur === 'canli') {
                        if (OT.durum === 'basladi') { oscBasla(OT.kalan); return; }
                        kutu.innerHTML = '<div class="osc-sp-bekle"><span class="osc-sp-nokta"><i></i><i></i><i></i></span><b>Öğretmeninin sınavı başlatması bekleniyor</b><small>Bu sayfayı kapatma. Sınav başlayınca kendiliğinden açılacak.</small></div>';
                        const t = setInterval(function () {
                            oscAjax('osc_sp_durum', oscOt()).then(function (x) {
                                if (!x || !x.success) return;
                                if (x.data.durum === 'basladi') { clearInterval(t); oscBasla(x.data.kalan); }
                                else if (x.data.durum === 'bitti') { clearInterval(t); kutu.innerHTML = '<div class="osc-sp-mesaj kirmizi">Bu oturum sona erdi.</div>'; }
                            }).catch(function () {});
                        }, 3000);
                        return;
                    }
                    if (OT.katilim_durum === 'cozuyor') { oscBasla(OT.kalan); return; }
                    kutu.innerHTML = '<div class="osc-sp-odev">' + (OT.son_tarih_metin ? '<div class="osc-sp-son">Son teslim: <b>' + oscEsc(OT.son_tarih_metin) + '</b></div>' : '') + '<button type="button" class="osc-btn-modern-start" data-x="basla">SINAVA BAŞLA <span class="dashicons dashicons-arrow-right-alt2" style="margin-top:4px"></span></button><small>' + (OT.sure ? 'Başladıktan sonra ' + OT.sure + ' dakikan olacak; süre dolunca sınav kendiliğinden teslim edilir.' : 'Süre sınırı yok; son teslim tarihine kadar bitirmelisin.') + '</small></div>';
                    kutu.querySelector('[data-x=basla]').onclick = function (e) {
                        e.target.disabled = true;
                        oscAjax('osc_sp_basla', oscOt()).then(function (x) { if (!x || !x.success) { e.target.disabled = false; alert((x && x.data) || 'Başlatılamadı'); return; } OT.cevaplar = x.data.cevaplar || OT.cevaplar; oscBasla(x.data.kalan); }).catch(function () { e.target.disabled = false; alert('Bağlantı hatası'); });
                    };
                }
                if (OT) { if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', oscOturumAc); else setTimeout(oscOturumAc, 0); }

                                const oscAjaxUrl = '<?php echo admin_url('admin-ajax.php'); ?>';
                const oscNonce = '<?php echo wp_create_nonce('osc_quiz_nonce'); ?>';

                // Öğrenci Adını Gerçek Veritabanına (AJAX) Kaydetme
                window.oscSaveScore = function(id) {
                    const nameInput = document.getElementById(`osc-student-name-${id}`);
                    const name = nameInput.value.trim();
                    const btn = nameInput.nextElementSibling;
                    
                    if(!name) { 
                        nameInput.style.borderColor = '#ef4444';
                        nameInput.placeholder = 'Lütfen adını gir!';
                        return; 
                    }
                    
                    const score = document.getElementById(`osc-final-score-${id}`).innerText;
                    
                    // Yükleniyor efekti
                    btn.innerText = 'Gönderiliyor...';
                    btn.disabled = true;
                    btn.style.opacity = '0.7';

                    const formData = new URLSearchParams();
                    formData.append('action', 'osc_save_score');
                    formData.append('quiz_id', id);
                    formData.append('name', name);
                    formData.append('score', score);
                    formData.append('nonce', oscNonce);

                    fetch(oscAjaxUrl, {
                        method: 'POST',
                        body: formData
                    })
                    .then(res => res.json())
                    .then(res => {
                        if(res.success) {
                            // Giriş alanını başarı mesajıyla değiştir
                            document.getElementById(`osc-name-input-area-${id}`).innerHTML = '<div style="color:#10b981; font-weight:800; font-size:16px; margin-bottom:20px;">🎉 Tebrikler! Puanın Soruİndir sistemine kaydedildi.</div>';
                            
                            // Veritabanından gelen global tabloyu çiz
                            window.oscRenderLeaderboard(id, res.data);
                        }
                    })
                    .catch(err => {
                        btn.innerText = 'Kaydet';
                        btn.disabled = false;
                        btn.style.opacity = '1';
                        alert('Bağlantı hatası oluştu, lütfen tekrar dene.');
                    });
                }

                // Global Liderlik Tablosunu Ekrana Çizdirme İşlevi
                window.oscRenderLeaderboard = function(id, leaders) {
                    const lbContainer = document.getElementById(`osc-leaderboard-${id}`);
                    const lbList = document.getElementById(`osc-lb-list-${id}`);
                    
                    if(!leaders || leaders.length === 0) return;
                    
                    let html = '';
                    leaders.forEach((l, index) => {
                        let rankClass = '';
                        let rankIcon = (index + 1) + '.';
                        
                        if(index === 0) { rankClass = 'top-1'; rankIcon = '🥇'; }
                        else if(index === 1) { rankClass = 'top-2'; rankIcon = '🥈'; }
                        else if(index === 2) { rankClass = 'top-3'; rankIcon = '🥉'; }
                        
                        html += `<div class="osc-lb-item ${rankClass}">
                                    <div class="osc-lb-rank">${rankIcon}</div>
                                    <div class="osc-lb-name">${l.name} <span style="font-size:11px; color:#94a3b8; font-weight:normal; margin-left:8px;">${l.date || ''}</span></div>
                                    <div class="osc-lb-score">%${l.score}</div>
                                 </div>`;
                    });
                    
                    lbList.innerHTML = html;
                    lbContainer.style.display = 'block';
                    
                    // Tabloya doğru yumuşak kaydırma
                    setTimeout(() => {
                        lbContainer.scrollIntoView({behavior: "smooth", block: "center"});
                    }, 300);
                };




                                window.oscShowMistakes = function(id) {
                    if(id !== quizId) return;
                    const area = document.getElementById(`osc-mistakes-area-${id}`);
                    if(area.style.display === 'block') { area.style.display = 'none'; return; }
                    let html = '<h3 style="margin-top:0; margin-bottom:15px; color:#1e293b; border-bottom:2px solid #e2e8f0; padding-bottom:10px;">Yanlış Cevaplanan Sorular</h3>';
                    const mistakes = state.history.filter(h => !h.isCorrect);
                    if(mistakes.length === 0) { html += '<p style="color:#10b981; font-weight:bold;">Harika! Hiç yanlışınız yok.</p>'; }
                    else {
                        mistakes.forEach(m => {
                            const q = config.questions[m.qIdx];
                            html += `<div style="background:#fff; padding:15px; border-radius:8px; border-left:4px solid #ef4444; margin-bottom:15px; box-shadow:0 2px 5px rgba(0,0,0,0.05);">`;
                            html += `<strong style="color:#3b82f6;">Soru ${m.qIdx + 1}:</strong><br>`;
                            if(q.paragraph) html += `<div style="font-size:13px; color:#64748b; margin:8px 0; background:#f1f5f9; padding:10px; border-radius:6px;">${q.paragraph}</div>`;
                            html += `<div style="font-weight:bold; margin-bottom:10px; color:#334155;">${q.root || q.text}</div>`;
                            if(q.type === 'classic') {
                                const lbl = m.verdict === 'partial' ? '½ Kısmen doğru – yarım puan (benzerlik %' + (m.sim||0) + ')' : (m.verdict === 'empty' ? 'Boş bırakıldı' : 'Model cevapla örtüşmüyor (benzerlik %' + (m.sim||0) + ')');
                                html += `<div style="color:#b45309; font-size:13px; font-weight:700; margin-bottom:6px;">${lbl}</div>`;
                                html += `<div style="color:#334155; font-size:14px; margin-bottom:5px;"><strong>Sizin Cevabınız:</strong> ${m.userAns ? OSCGrade.esc(m.userAns) : 'Boş'}</div>`;
                                html += `<div style="color:#10b981; font-size:14px;"><strong>Doğru Cevap:</strong> ${q.options.A}</div>`;
                            } else if(q.type === 'gap') {
                                html += `<div style="color:#ef4444; font-size:14px; margin-bottom:5px;"><strong>Sizin Cevabınız:</strong> ${m.userAns || 'Boş'}</div>`;
                                html += `<div style="color:#10b981; font-size:14px;"><strong>Doğru Cevap:</strong> ${q.options.A}</div>`;
                            } else {
                                const opts = q.type === 'truefalse' ? {A:'Doğru', B:'Yanlış'} : q.options;
                                html += `<div style="color:#ef4444; font-size:14px; margin-bottom:5px;"><strong>Sizin Cevabınız:</strong> ${m.userKey ? opts[m.userKey] : 'Boş'}</div>`;
                                html += `<div style="color:#10b981; font-size:14px;"><strong>Doğru Cevap:</strong> ${opts[q.correct]}</div>`;
                                                        }
                            html += `</div>`;
                        });
                        
                                                // YANLIŞLARI İNCELE SONU REKLAMI (Şeffaf ve Esnek)
                        const rawAdMistakes = <?php echo json_encode(stripslashes($ad_mistakes)); ?>;
                        if(rawAdMistakes && rawAdMistakes.trim() !== '') {
                            html += `<div style="margin-top:20px; text-align:center; display:flex; justify-content:center;">`;
                            html += rawAdMistakes;
                            html += `</div>`;
                        }

                    }
                    area.innerHTML = html;
                    area.style.display = 'block';

                    setTimeout(() => area.scrollIntoView({behavior: "smooth", block: "nearest"}), 100);
                }

                window.oscShare = function(platform, id) {

                    const score = document.getElementById(`osc-final-score-${id}`).innerText;
                    const url = encodeURIComponent(window.location.href);
                    const text = encodeURIComponent(`Bu testi %${score} başarı ile tamamladım! Sende durum ne? 🏆 `);
                    let shareUrl = '';
                    
                    if(platform === 'whatsapp') {
                        shareUrl = `https://api.whatsapp.com/send?text=${text}${url}`;
                    } else if(platform === 'twitter') {
                        shareUrl = `https://twitter.com/intent/tweet?text=${text}&url=${url}`;
                    } else if(platform === 'facebook') {
                        shareUrl = `https://www.facebook.com/sharer/sharer.php?u=${url}&quote=${text}`;
                    }
                    
                                        window.open(shareUrl, '_blank', 'width=600,height=500,toolbar=0,menubar=0,location=0,status=0,scrollbars=1,resizable=1,left=0,top=0');
                };
							// SİTENE EKLE (EMBED) KODLARI
                window.oscShowEmbed = function(id) {
                    const area = document.getElementById(`osc-embed-area-${id}`);
                    const textarea = document.getElementById(`osc-embed-code-${id}`);
                    
                    // Sitenin ana dizinini alıp, özel iframe şifremizi DOĞRUDAN TEST ID'Sİ İLE ekliyoruz
                    const embedUrl = '<?php echo site_url(); ?>/?osc_embed=' + id;
                    const iframeCode = `<iframe src="${embedUrl}" width="100%" height="800" frameborder="0" style="border:none; border-radius:12px; box-shadow:0 4px 15px rgba(0,0,0,0.1);"></iframe>`;
                    
                    textarea.value = iframeCode;
                    
                    // Kutuyu Aç / Kapat (Toggle)
                    if(area.style.display === 'none') {
                        area.style.display = 'block';
                    } else {
                        area.style.display = 'none';
                    }
                };

                window.oscCopyEmbed = function(id) {
                    const textarea = document.getElementById(`osc-embed-code-${id}`);
                    const btn = document.getElementById(`osc-copy-btn-${id}`);
                    
                    // Metni kopyala
                    textarea.select();
                    textarea.setSelectionRange(0, 99999); // Mobil cihazlar için güvenli kopyalama
                    
                    navigator.clipboard.writeText(textarea.value).then(() => {
                        const originalHTML = btn.innerHTML;
                        btn.innerHTML = '<span class="dashicons dashicons-yes"></span> Kopyalandı!';
                        btn.style.background = '#10b981'; // Başarılı olunca yeşile dön
                        
                        // 2 saniye sonra butonu eski haline (mavi) döndür
                        setTimeout(() => {
                            btn.innerHTML = originalHTML;
                            btn.style.background = '#3b82f6';
                        }, 2000);
                    }).catch(err => {
                        console.error('Kopyalama başarısız!', err);
                        // Eski tarayıcılar için yedek yöntem
                        document.execCommand('copy');
                        btn.innerHTML = 'Kopyalandı!';
                    });
                };

         // PDF / YAZDIRMA ŞABLONU OLUŞTURMA VE TETİKLEME
                window.oscPrintPDF = function(id) {
                    let printDiv = document.getElementById('osc-print-area');
                    
                    // Varsa eski çıktı alanını temizle, yenisini oluştur
                    if(printDiv) { printDiv.remove(); }
                    
                                        printDiv = document.createElement('div');
                    printDiv.id = 'osc-print-area';
                    // DİKKAT: Burada inline olarak display: none YAPMIYORUZ! Boş PDF hatasının sebebi buydu.
                    // Gizleme işlemini artık CSS'teki @media screen kuralı kusursuzca halledecek.
                    document.body.appendChild(printDiv);

                    
                    const quizTitle = <?php echo json_encode(get_the_title($post_id)); ?>;
                    
                    // Şablon Başlangıcı (Sabit Çizgi, Filigran ve Başlık)
                    let html = '<div class="osc-print-center-line"></div>';
                    html += '<div class="osc-print-watermark">soruindir.net</div>';
                    html += '<div class="osc-print-header"><h2>' + quizTitle + '</h2></div>';
                    html += '<div class="osc-print-columns">';

                    // Soruları Döngüyle Ekle
                    config.questions.forEach((q, i) => {
                        html += '<div class="osc-print-q">';
                        html += '<div class="osc-print-q-num">' + (i + 1) + '.</div>';
                        
                        let mainText = '';
                        if(q.paragraph) mainText += '<div class="osc-print-para">' + q.paragraph + '</div>';
                        mainText += '<div class="osc-print-root">' + (q.root || q.text) + '</div>';
                        html += '<div>' + mainText + '</div>';
                        
                        // Şıklar
                        html += '<div class="osc-print-opts">';
                        if(q.type === 'classic') { html += '<span style="display:block;width:100%">' + '<span style="display:block;border-bottom:1px dotted #333;height:22px;margin-bottom:6px"></span>'.repeat(4) + '</span>'; } else if(q.type === 'gap') {
                            html += '<span>....................................................................</span>';
                        } else if(q.type === 'truefalse') {
                            html += '<span>A) Doğru</span><span>B) Yanlış</span>';
                        } else {
                            ['A', 'B', 'C', 'D', 'E'].forEach(k => {
                                if(q.options && q.options[k]) {
                                    html += '<span>' + k + ') ' + q.options[k] + '</span>';
                                }
                            });
                        }
                        html += '</div></div>';
                    });
                    
                    html += '</div>'; // Sütun bitişi
                    
                    // Cevap Anahtarını Topla ve Ekle
                    let answerArr = [];
                    config.questions.forEach((q, i) => {
                        // Boşluk doldurma (gap) ise metni, çoktan seçmeliyse şıkkın harfini alır
                        let ans = q.type === 'gap' ? (q.options.A || '') : (q.type === 'classic' ? String(q.options.A || '').replace(/<[^>]*>/g, '').slice(0, 60) : (q.correct || ''));
                        answerArr.push((i + 1) + '-' + ans);
                    });
                    
                    html += '<div class="osc-print-answer-key"><strong>CEVAP ANAHTARI:</strong> ' + answerArr.join(' , ') + '</div>';
                    
                    printDiv.innerHTML = html;
                    
                    // DOM'un güncellenmesini bekleyip yazdır komutunu ver
                    setTimeout(() => {
                        window.print();
                        
                        // TEMİZLİK: Yazdırma işlemi bittikten kısa bir süre sonra HTML'i tamamen sil
                        setTimeout(() => {
                            if(document.getElementById('osc-print-area')) {
                                document.getElementById('osc-print-area').remove();
                            }
                        }, 2000);
                        
                    }, 300);
                };

            })();
            </script>


            <?php
            return ob_get_clean();
        }

        public function add_meta_box() { add_meta_box('osc_builder', 'Test Yönetim Paneli', array($this, 'render_admin'), 'osc_quiz', 'normal', 'high'); }

        public function render_admin($post) {
            $data = get_post_meta($post->ID, '_osc_data', true);
            $settings = get_post_meta($post->ID, '_osc_settings', true);
            wp_nonce_field('osc_save', 'osc_nonce');
            ?>
            <div class="osc-admin-wrap">
                <div class="osc-panel" style="background:#e8f4fd; border-color:#d0e6f9;">
                    <h3 style="margin-top:0;">TEST KISA KODU (Bunu Kopyalayın)</h3>
                    <p style="margin-bottom:5px; font-size:13px; color:#555;">Testi yazı içine eklemek için aşağıdaki kodu kopyalayıp editörünüze yapıştırın:</p>
