            var H = pagesWH[pi][1];
            return fs.filter(function (f) {
                var c = cnt[k(f)];
                if (c < 2) return true;
                var inMargin = f.y0 > H * 0.85 || f.y1 < H * 0.12;
                return !(inMargin || c >= Math.max(3, Math.ceil(np * 0.6)));
