  /* ================= yapay zekâ ile toplu doldurma ================= */
  var uP = { donem: (SNR.donemler || [1])[0], yazili: 'hepsi', sinif: 0, ders: '', carpan: 4, en_az: 6, test: 25, dogrula: 1, butce: 15 }, uZ = 0;
  function vUret() {
