    return { t: { kademe: sinif <= 8 ? 'ortaokul' : 'lise', ders: ders, sinif: sinif, donem: donem || 2, baslik: sayfaAd, senaryolar: snr, ulke: ulke, satirlar: satirlar } };
  }
